def compute(vars):
    old_balance = vars["v1"]
    new_balance = vars["v2"]
    change = new_balance - old_balance
    return {
        "value": change,
        "trace": {
            "old_balance_2018": old_balance,
            "new_balance_2019": new_balance,
            "change": change,
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": None
            }
        }
    }
